import{z as d,x as A,o as s,c as p,q as l,j as o,D as r,d as e,s as n,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"语法制导翻译","description":"","frontmatter":{"title":"语法制导翻译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syntax-directed-translation.md","filePath":"cs/syntax-directed-translation.md","lastUpdated":1791063341000}'),B={name:"cs/syntax-directed-translation.md"};function D(m,a,c,T,h,S){const E=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=l('<h1 id="语法制导翻译" tabindex="-1">语法制导翻译 <a class="header-anchor" href="#语法制导翻译" aria-label="Permalink to &quot;语法制导翻译&quot;">​</a></h1><div class="epigraph"><p>归约（或下降）走到产生式，就执行翻译方案：建结点、查表、或发出中间代码。语法驱动控制流，语义在动作里。</p><footer>—— 据龙书第 5 章语法制导翻译；Aho and Ullman 的翻译方案传统整理</footer></div><p>上一课<a href="/cs/attribute-grammar">属性文法</a>给出方程。缺口是编译器里那份<strong>可执行的方案</strong>：语法制导翻译（SDT）把方程编成与产生式绑定的代码片段。主干<a href="/cs/ir-three-address">三地址</a>是动作的目标之一。本课钉「何时发代码、值存在哪」，不重开 SSA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>属性方程是数学；SDT 是实现：<code>E → E1 + T { emit(add); E.addr = newtemp(); }</code>。自底向上：动作在右部末尾最自然（S 属性）。要在右部中间用继承值，须改写成标记非终结符或先建树再走第二遍。缺口是<strong>动作放置</strong>，不是再定义加号语义。</p><p>与访问者：先完整 AST 再翻译，等于把 SDT 从分析期推迟。两种都合法；生成器习惯分析期动作，手写前端习惯后遍。</p><p><span class="marginnote">数字实例：解析 2+3 时，动作先为 2、3 各取一个名字（t0=2、t1=3），归约加法时发出 add t2, t0, t1 并把 t2 压栈。「值存在哪」的答案就是这张语义栈，不是全局变量。</span></p><h3 id="emit-不是优化" tabindex="-1"><code>emit</code> 不是优化 <a class="header-anchor" href="#emit-不是优化" aria-label="Permalink to &quot;`emit` 不是优化&quot;">​</a></h3><p>此处发出的是忠实 IR。常量折叠可在动作里做，但那是优化课的对象；本课只要求结构对应。不要在 SDT 里做寄存器分配。</p><p><span class="marginnote">龙书把 SDT 与 AG 放在同章。Appel 的教材偏向先树后 IR。本进阶课二者都认：生成器路径 vs 显式 AST 路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定 IR（三地址、树 IR）。为每个产生式写动作：叶结点从 <code>yylval</code> 取值；内部结点综合地址或树指针。控制流：<code>if</code> 产生式留下回填洞，或生成带标号的跳转——与后课中端 CFG 衔接，本课只发指令序列。</p>',12)),(s(),o(i,null,{default:r(()=>[n(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROD%5B%22%E4%BA%A7%E7%94%9F%E5%BC%8F%22%5D%20--%3E%20ACT%5B%22%E7%BF%BB%E8%AF%91%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20ACT%20--%3E%20IR%5B%22IR%20%2F%20AST%22%5D%0A%20%20ACT%20--%3E%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E8%A1%A8%E5%89%AF%E4%BD%9C%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("错误节点：动作应跳过或发 trap，不要当合法加号去折叠。接"),t("a",{href:"/cs/parse-error-recovery"},"错误恢复"),e("。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"左递归产生式的 SDT 自然得到左结合的代码序。右递归则反向，要小心临时值寿命。继承属性在 LR 里常用语义栈上的「已分析兄长」。",-1)),(s(),o(i,null,{default:r(()=>[n(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E8%AF%BB%E5%88%B0%20a%EF%BC%9A%E4%BB%8E%20yylval%20%E5%8F%96%20addr%22%5D%20--%3E%20RED1%5B%22%E5%BD%92%E7%BA%A6%20F%20%E5%88%B0%20a%EF%BC%9A%E5%80%BC%E5%8E%8B%E8%AF%AD%E4%B9%89%E6%A0%88%22%5D%0A%20%20RED1%20--%3E%20OP%5B%22%E8%AF%BB%E5%88%B0%20%2B%EF%BC%9A%E7%AE%97%E7%AC%A6%E5%85%A5%E6%A0%88%22%5D%0A%20%20OP%20--%3E%20L2%5B%22%E8%AF%BB%E5%88%B0%20b%EF%BC%9A%E5%90%8C%E7%90%86%E5%8E%8B%E6%A0%88%22%5D%0A%20%20L2%20--%3E%20RED2%5B%22%E7%BB%A7%E7%BB%AD%E5%BD%92%E7%BA%A6%20T%E3%80%81E%20%E9%83%A8%E5%88%86%22%5D%0A%20%20RED2%20--%3E%20RED3%5B%22%E5%BD%92%E7%BA%A6%20E%20%E5%88%B0%20E1%20%2B%20T%EF%BC%9A%E5%8A%A8%E4%BD%9C%E8%A7%A6%E5%8F%91%22%5D%0A%20%20RED3%20--%3E%20EMIT%5B%22emit%20add%EF%BC%8Cnewtemp()%20%E5%8E%8B%E5%9B%9E%E6%A0%88%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">继承属性可以类比填表：综合属性像孩子把成绩单交给父母（自下而上汇总），继承属性像父母把家庭住址传给孩子（自上而下下发）。LR 栈只会自下而上，所以继承值要走「已分析兄长」这条旁路。</span></p><p>宏展开若发生在 SDT 之前，动作看见的已是展开后记号——本课序后段宏课再钉顺序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写指令选择，不引入 φ。后课默认：前端可用 SDT 得到 AST 或线性 IR。下一课：宏——在记号或树上做的另一类「翻译」，卫生问题从这里露出。</p><p>不要把 SDT 当成类型健全性证明；类型规则下一单元。</p><p><span class="marginnote">常见误区：在 SDT 动作里顺手做寄存器分配或指令调度。动作只负责忠实翻译出 IR，寄存器怎么分、指令怎么排是后端的事；前端越界做了，中端优化反而无从下手。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SDT：产生式绑定动作，驱动翻译。</li><li>S 属性可在 LR 归约时执行；更复杂就先树后遍。</li><li>动作发 IR，不做分配与调度。</li><li>出处：Aho et al., 龙书第 5 章；对照 Appel 的树转 IR。</li></ul>',8))])}const C=d(B,[["render",D]]);export{u as __pageData,C as default};
